import type {
  ExerciseTrackingType,
  StructuredExerciseInput,
  TrainingGoalType,
  UnilateralMode,
} from "@/lib/types";

export type ExerciseCategory =
  | "mobility"
  | "strength"
  | "cardio"
  | "core"
  | "running_prep"
  | "recovery"
  | "athletic";

export type MovementPattern =
  | "squat"
  | "hinge"
  | "lunge"
  | "push"
  | "pull"
  | "carry"
  | "core"
  | "mobility"
  | "run"
  | "walk"
  | "calf"
  | "lateral"
  | "power";

export type DifficultyTier = "intro" | "foundation" | "intermediate";

export type CautionTag =
  | "knee"
  | "back"
  | "shoulder"
  | "ankle"
  | "hamstring"
  | "impact"
  | "overhead"
  | "loaded_spine";

export type ExerciseTrackingMetadata = {
  trackingType: ExerciseTrackingType;
  unilateralMode: UnilateralMode;
  loadUnit: "lb" | "kg" | null;
  supportedLoadUnits: Array<"lb" | "kg">;
  distanceUnit: "mi" | "km" | "m" | null;
  supportedDistanceUnits: Array<"mi" | "km" | "m">;
  primaryValueLabel: string | null;
  secondaryValueLabel: string | null;
};

export type ExerciseCatalogItem = StructuredExerciseInput &
  ExerciseTrackingMetadata & {
    id: string;
    category: ExerciseCategory;
    movementPattern: MovementPattern;
    equipmentTags: string[];
    goalTags: TrainingGoalType[];
    difficultyTier: DifficultyTier;
    cautionTags: CautionTag[];
    traitTags: string[];
    preferenceTags: string[];
  };

export const exerciseCategories: Array<{
  value: ExerciseCategory;
  label: string;
}> = [
  { value: "mobility", label: "Mobility" },
  { value: "strength", label: "Strength" },
  { value: "cardio", label: "Cardio" },
  { value: "core", label: "Core" },
  { value: "running_prep", label: "Running prep" },
  { value: "recovery", label: "Recovery" },
  { value: "athletic", label: "Athletic" },
];

const completionMetadata: ExerciseTrackingMetadata = {
  trackingType: "completion",
  unilateralMode: "bilateral",
  loadUnit: null,
  supportedLoadUnits: [],
  distanceUnit: null,
  supportedDistanceUnits: [],
  primaryValueLabel: "Completion",
  secondaryValueLabel: null,
};

const repsMetadata = (
  unilateralMode: UnilateralMode = "bilateral",
): ExerciseTrackingMetadata => ({
  trackingType: "reps_only",
  unilateralMode,
  loadUnit: null,
  supportedLoadUnits: [],
  distanceUnit: null,
  supportedDistanceUnits: [],
  primaryValueLabel: "Reps",
  secondaryValueLabel: null,
});

const weightRepsMetadata = (
  unilateralMode: UnilateralMode = "bilateral",
  labels: { primaryValueLabel?: string; secondaryValueLabel?: string } = {},
): ExerciseTrackingMetadata => ({
  trackingType: "weight_reps",
  unilateralMode,
  loadUnit: "lb",
  supportedLoadUnits: ["lb", "kg"],
  distanceUnit: null,
  supportedDistanceUnits: [],
  primaryValueLabel: labels.primaryValueLabel ?? "Load",
  secondaryValueLabel: labels.secondaryValueLabel ?? "Reps",
});

const durationMetadata = (
  unilateralMode: UnilateralMode = "bilateral",
): ExerciseTrackingMetadata => ({
  trackingType: "duration",
  unilateralMode,
  loadUnit: null,
  supportedLoadUnits: [],
  distanceUnit: null,
  supportedDistanceUnits: [],
  primaryValueLabel: "Duration",
  secondaryValueLabel: null,
});

const distanceMetadata = (
  unilateralMode: UnilateralMode = "bilateral",
  unit: "mi" | "km" | "m" = "m",
): ExerciseTrackingMetadata => ({
  trackingType: "distance",
  unilateralMode,
  loadUnit: null,
  supportedLoadUnits: [],
  distanceUnit: unit,
  supportedDistanceUnits: ["m", "km", "mi"],
  primaryValueLabel: "Distance",
  secondaryValueLabel: null,
});

const distanceDurationMetadata: ExerciseTrackingMetadata = {
  trackingType: "distance_duration",
  unilateralMode: "bilateral",
  loadUnit: null,
  supportedLoadUnits: [],
  distanceUnit: "mi",
  supportedDistanceUnits: ["mi", "km", "m"],
  primaryValueLabel: "Distance",
  secondaryValueLabel: "Duration",
};

